// ScratchPad/Session16/Session16VarianceDemo.cs
public interface ISource<out T>
{
    T Get();
}

public sealed class SingleSource<T> : ISource<T>
{
    private readonly T _value;

    public SingleSource(T value)
    {
        _value = value;
    }

    public T Get()
    {
        return _value;
    }
}

public interface ISink<in T>
{
    void Add(T item);
}

public sealed class CountingSink<T> : ISink<T>
{
    public int Count { get; private set; }

    public void Add(T item)
    {
        Count++;
    }
}

public sealed class Session16VarianceDemo
{
    public void Run()
    {
        var employee = new Employee(16, "Avery", new Address { City = "Springfield" });

        ISource<Employee> employeeSource = new SingleSource<Employee>(employee);
        ISource<object> objectSource = employeeSource;
        object produced = objectSource.Get();
        Console.WriteLine($"Produced runtime type: {produced.GetType().Name}");

        // Unsafe direction: an object source might produce something other than Employee.
        // ISource<Employee> invalidSource = objectSource;

        var countingObjectSink = new CountingSink<object>();
        ISink<Employee> employeeSink = countingObjectSink;
        employeeSink.Add(employee);
        Console.WriteLine($"Consumed employees: {countingObjectSink.Count}");

        // Unsafe direction: an Employee sink cannot accept every possible object.
        // ISink<object> invalidSink = employeeSink;
    }
}

